get itemIds() {
  return Array.from(this.children, element =>
    element.getAttribute("item-id")
  );
}

/**
 * If the contents of this target differ from the currently saved
 * configuration.
 *
 * @type {boolean}
 */
get hasChanges() {
  return this.itemIds.join(",") !== this.getAttribute("current-items");
}
